//! Generated gRPC code for the Giles plugin and admin protocols.
//!
//! One module per Protobuf package, generated by `prost` and `tonic` from the sources in the
//! repository's `proto/` directory: messages, and a client and a server for every service. See
//! `Docs/technical/protocols.md` for the packages, their conventions, and how they map to
//! `giles-types`.
//!
//! This crate holds only the wire types and the constants of the launch handshake
//! ([`handshake`]). Conversions to and from `giles-types` belong to the code that speaks the
//! protocol: the plugin SDK and the core's `Remote*` adapters.

/// The largest gRPC message, encoded or decoded, that Giles sends or accepts: 16 MiB.
///
/// Set it on every client and server (`max_decoding_message_size` and
/// `max_encoding_message_size`) in place of `tonic`'s 4 MiB default, which a long request would
/// exceed. Media never counts against it: it moves as blobs (PLAN section 8.1).
pub const MAX_MESSAGE_SIZE: usize = 16 * 1024 * 1024;

/// The most data one `BlobChunk` carries: 1 MiB (PLAN section 8.3).
pub const MAX_BLOB_CHUNK_SIZE: usize = 1024 * 1024;

/// The encoded `google.protobuf.FileDescriptorSet` of every package, with its imports. For gRPC
/// server reflection.
pub const FILE_DESCRIPTOR_SET: &[u8] =
    include_bytes!(concat!(env!("OUT_DIR"), "/giles_descriptor.bin"));

pub mod handshake;

pub mod types {
    //! `giles.types.v1`: the shared message types, mirroring `giles-types`.

    /// Version 1 of the package.
    #[allow(missing_docs, clippy::all, clippy::pedantic)]
    pub mod v1 {
        tonic::include_proto!("giles.types.v1");
    }
}

pub mod plugin {
    //! `giles.plugin.v1`: the base service every gRPC plugin serves, and blob transfer.

    /// Version 1 of the package.
    #[allow(missing_docs, clippy::all, clippy::pedantic)]
    pub mod v1 {
        tonic::include_proto!("giles.plugin.v1");
    }
}

pub mod provider {
    //! `giles.provider.v1`: provider plugins. For now only the capabilities in `Describe`.

    /// Version 1 of the package.
    #[allow(missing_docs, clippy::all, clippy::pedantic)]
    pub mod v1 {
        tonic::include_proto!("giles.provider.v1");
    }
}

pub mod channel {
    //! `giles.channel.v1`: channel plugins.

    /// Version 1 of the package.
    #[allow(missing_docs, clippy::all, clippy::pedantic)]
    pub mod v1 {
        tonic::include_proto!("giles.channel.v1");
    }
}

pub mod admin {
    //! `giles.admin.v1`: the core's admin service, for the CLI and the web admin pages.

    /// Version 1 of the package.
    #[allow(missing_docs, clippy::all, clippy::pedantic)]
    pub mod v1 {
        tonic::include_proto!("giles.admin.v1");
    }
}

#[cfg(test)]
mod tests {
    use prost::Message as _;

    use super::channel::v1::{
        ChannelEvent, ChannelStatus, EventsResponse, InboundMessage, NeedsAuth, channel_event,
        channel_status, needs_auth,
    };
    use super::plugin::v1::{BlobChunk, blob_chunk};
    use super::types::v1::{
        BlobRef, Block, ConversationKind, ConversationRef, ImageBlock, Opaque, ReasoningBlock,
        TextBlock, ToolResultBlock, block,
    };
    use super::*;

    fn round_trip<T: prost::Message + Default + PartialEq + std::fmt::Debug>(value: &T) {
        let bytes = value.encode_to_vec();
        assert_eq!(&T::decode(bytes.as_slice()).unwrap(), value);
    }

    fn blob(name: Option<&str>) -> BlobRef {
        BlobRef {
            id: "h1".into(),
            media_type: "image/png".into(),
            size: 5,
            name: name.map(Into::into),
        }
    }

    #[test]
    fn nested_block_oneofs_round_trip() {
        let result = Block {
            block: Some(block::Block::ToolResult(ToolResultBlock {
                tool_use_id: "toolu_1".into(),
                content: vec![
                    Block {
                        block: Some(block::Block::Text(TextBlock {
                            text: String::new(),
                        })),
                    },
                    Block {
                        block: Some(block::Block::Image(ImageBlock {
                            media: Some(blob(None)),
                        })),
                    },
                ],
                is_error: true,
            })),
        };
        round_trip(&result);

        // Set-but-empty optional and oneof fields stay distinguishable from unset ones.
        let reasoning = Block {
            block: Some(block::Block::Reasoning(ReasoningBlock {
                text: Some(String::new()),
                opaque: Some(Opaque {
                    api: "anthropic".into(),
                    data_json: r#"{"signature":"c2ln","n":18446744073709551615}"#.into(),
                }),
            })),
        };
        round_trip(&reasoning);
        let decoded = Block::decode(reasoning.encode_to_vec().as_slice()).unwrap();
        let Some(block::Block::Reasoning(r)) = decoded.block else {
            panic!("not reasoning: {decoded:?}");
        };
        assert_eq!(r.text.as_deref(), Some(""));
    }

    #[test]
    fn channel_events_round_trip() {
        let message = EventsResponse {
            event: Some(ChannelEvent {
                event_id: "wamid.1".into(),
                event: Some(channel_event::Event::Message(InboundMessage {
                    conversation: Some(ConversationRef {
                        id: "120363@g.us".into(),
                        kind: ConversationKind::Group.into(),
                        title: Some("Family".into()),
                    }),
                    sender: "+15551234567".into(),
                    sender_display_name: None,
                    text: "hi".into(),
                    attachments: vec![blob(Some("a.png"))],
                    reply_to: Some("3EB0".into()),
                    sent_at: Some(prost_types::Timestamp {
                        seconds: 1_792_670_400,
                        nanos: 500_000_000,
                    }),
                    sender_authenticated: true,
                    sender_aliases: vec!["123456789@lid".into()],
                    message_id: Some("3EB1".into()),
                })),
            }),
        };
        round_trip(&message);

        let status = ChannelEvent {
            event_id: "s1".into(),
            event: Some(channel_event::Event::Status(ChannelStatus {
                state: Some(channel_status::State::NeedsAuth(NeedsAuth {
                    challenge: Some(needs_auth::Challenge::QrCode("2@abc".into())),
                    expires_at: None,
                })),
            })),
        };
        round_trip(&status);
    }

    /// A `ChannelEvent` from a newer plugin, with an event variant this version doesn't know.
    #[derive(Clone, PartialEq, prost::Message)]
    struct FutureChannelEvent {
        #[prost(string, tag = "1")]
        event_id: String,
        #[prost(string, tag = "99")]
        reaction: String,
    }

    #[test]
    fn unknown_event_variant_decodes_with_its_id_and_no_event() {
        // The core acks such an event by id and ignores it (PLAN section 7.8).
        let future = FutureChannelEvent {
            event_id: "e1".into(),
            reaction: "thumbs-up".into(),
        };
        let event = ChannelEvent::decode(future.encode_to_vec().as_slice()).unwrap();
        assert_eq!(event.event_id, "e1");
        assert_eq!(event.event, None);
    }

    #[test]
    fn size_limits_match_the_plan() {
        assert_eq!(MAX_MESSAGE_SIZE, 16 * 1024 * 1024);
        assert_eq!(MAX_BLOB_CHUNK_SIZE, 1024 * 1024);
        let chunk = BlobChunk {
            part: Some(blob_chunk::Part::Data(vec![0; MAX_BLOB_CHUNK_SIZE])),
        };
        assert!(chunk.encoded_len() < MAX_MESSAGE_SIZE);
    }

    #[test]
    fn descriptor_set_has_every_package_and_service() {
        let set = prost_types::FileDescriptorSet::decode(FILE_DESCRIPTOR_SET).unwrap();
        let mut packages: Vec<&str> = set.file.iter().map(|f| f.package()).collect();
        packages.sort_unstable();
        packages.dedup();
        assert_eq!(
            packages,
            [
                "giles.admin.v1",
                "giles.channel.v1",
                "giles.plugin.v1",
                "giles.provider.v1",
                "giles.types.v1",
                "google.protobuf",
            ]
        );

        let mut services: Vec<String> = set
            .file
            .iter()
            .flat_map(|f| {
                f.service
                    .iter()
                    .map(|s| format!("{}.{}", f.package(), s.name()))
            })
            .collect();
        services.sort_unstable();
        assert_eq!(
            services,
            [
                admin::v1::admin_service_server::SERVICE_NAME,
                channel::v1::channel_service_server::SERVICE_NAME,
                plugin::v1::plugin_service_server::SERVICE_NAME,
            ]
        );
        assert_eq!(
            plugin::v1::plugin_service_server::SERVICE_NAME,
            "giles.plugin.v1.PluginService"
        );
    }
}
